import { Controller } from "@hotwired/stimulus"

// Dedicated TinyMCE controller - handles initialization and cleanup
export default class extends Controller {
  connect() {
    this.loadTinyMCE()
  }

  disconnect() {
    this.destroyEditor()
    this.disconnectVisibilityObserver()
  }

  loadTinyMCE() {
    // Check if TinyMCE is already loaded
    if (window.tinymce) {
      this.initEditor()
      this.setupVisibilityObserver()
      return
    }

    // Load TinyMCE from CDN
    const apiKey = this.getApiKey()
    const script = document.createElement('script')
    script.src = `https://cdn.tiny.cloud/1/${apiKey}/tinymce/8/tinymce.min.js`
    script.referrerPolicy = 'origin'

    script.onload = () => {
      console.log('TinyMCE loaded from CDN')
      this.initEditor()
      this.setupVisibilityObserver()
    }

    script.onerror = () => {
      console.error('Failed to load TinyMCE from CDN')
    }

    document.head.appendChild(script)
  }

  getApiKey() {
    // Try to get API key from meta tag
    const metaTag = document.querySelector('meta[name="tinymce-api-key"]')
    if (metaTag) {
      return metaTag.getAttribute('content') || 'no-api-key'
    }
    return 'no-api-key'
  }

  setupVisibilityObserver() {
    // Watch for visibility changes on parent elements
    this.visibilityObserver = new MutationObserver(() => {
      // If element becomes visible and TinyMCE is not initialized, init it
      if (this.element.offsetParent && !tinymce.get(this.element.id)) {
        console.log('Element became visible, initializing TinyMCE:', this.element.id)
        this.initEditor()
      }
    })

    // Observe class changes on parent elements (for hidden/show toggles)
    let parent = this.element.parentElement
    while (parent) {
      this.visibilityObserver.observe(parent, {
        attributes: true,
        attributeFilter: ['class']
      })
      parent = parent.parentElement
      // Stop at form level to avoid too many observers
      if (parent?.tagName === 'FORM') break
    }
  }

  disconnectVisibilityObserver() {
    if (this.visibilityObserver) {
      this.visibilityObserver.disconnect()
    }
  }

  initEditor() {
    // Skip if already initialized
    if (tinymce.get(this.element.id)) {
      console.log('TinyMCE already initialized for:', this.element.id)
      return
    }

    // Skip if element is not visible
    if (!this.element.offsetParent) {
      console.log('Element not visible, will init when visible:', this.element.id)
      return
    }

    console.log('Initializing TinyMCE for:', this.element.id)

    // Initialize TinyMCE with default config
    tinymce.init({
      target: this.element,
      menubar: false,
      plugins: 'lists link',
      toolbar: 'undo redo | bold italic underline | bullist numlist',
      height: 300,
      setup: (editor) => {
        editor.on('init', () => {
          console.log('TinyMCE ready:', this.element.id)
        })
      }
    }).catch(error => {
      console.error('TinyMCE initialization failed:', error)
    })
  }

  destroyEditor() {
    try {
      const editor = tinymce.get(this.element.id)
      if (editor) {
        console.log('Destroying TinyMCE editor:', this.element.id)
        editor.remove()
      }
    } catch (error) {
      console.error('Error destroying TinyMCE editor:', error)
    }
  }

  // Public method to manually reinitialize (called when parent element becomes visible)
  reinit() {
    this.destroyEditor()
    // Small delay to ensure DOM is settled
    setTimeout(() => this.initEditor(), 50)
  }
}

import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["container", "template"]

  connect() {
    this.fieldCount = 0
    this.fields = []
    this.initializeExistingFields()
  }

  initializeExistingFields() {
    // Check if there are existing fields in the container
    const existingFields = this.containerTarget.querySelectorAll('[data-field-index]')
    this.fieldCount = existingFields.length

    // If no existing fields, add one empty field
    if (this.fieldCount === 0) {
      this.addField()
    }
  }

  addField() {
    const fieldHtml = `
      <div class="flex items-center space-x-2 mb-2" data-field-index="${this.fieldCount}">
        <input type="text"
               placeholder="Group"
               class="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none"
               data-action="input->dynamic-fields#updateField"
               data-field-type="group">
        <input type="text"
               placeholder="Name"
               class="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none"
               data-action="input->dynamic-fields#updateField"
               data-field-type="name">
        <input type="text"
               placeholder="Value"
               class="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none"
               data-action="input->dynamic-fields#updateField"
               data-field-type="value">
        <button type="button"
                class="text-red-500 hover:text-red-700 p-2"
                data-action="click->dynamic-fields#removeField">
          <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path>
          </svg>
        </button>
      </div>
    `

    this.containerTarget.insertAdjacentHTML('beforeend', fieldHtml)
    this.fieldCount++
    this.updateJsonField()
  }

  removeField(event) {
    const fieldRow = event.target.closest('[data-field-index]')
    if (fieldRow) {
      fieldRow.remove()
      this.updateJsonField()
    }
  }

  updateField() {
    this.updateJsonField()
  }

  updateJsonField() {
    const groupedFields = {}
    const fieldRows = this.containerTarget.querySelectorAll('[data-field-index]')

    fieldRows.forEach(row => {
      const groupInput = row.querySelector('[data-field-type="group"]')
      const nameInput = row.querySelector('[data-field-type="name"]')
      const valueInput = row.querySelector('[data-field-type="value"]')

      const group = groupInput.value.trim()
      const name = nameInput.value.trim()
      const value = valueInput.value.trim()

      if (group && name && value) {
        // Initialize group array if doesn't exist
        if (!groupedFields[group]) {
          groupedFields[group] = []
        }

        // Add name-value pair to the group
        groupedFields[group].push({
          name: name,
          value: value
        })
      }
    })

    // Update the hidden field with JSON
    const hiddenField = document.querySelector('[name="product[specification_pdp]"]')
    if (hiddenField) {
      hiddenField.value = JSON.stringify(groupedFields)
      // Trigger input event to update main form JSON
      hiddenField.dispatchEvent(new Event('input', { bubbles: true }))
    }

    // Trigger custom event for the main form controller
    this.dispatch('fieldUpdated', { detail: { field: 'specification_pdp', value: groupedFields } })
  }
}

