import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["field"]

  connect() {
    console.log("ProductTypeController connected")
    console.log("Field targets found:", this.fieldTargets.length)
    this.toggleFields()
  }

  toggleFields(event) {
    const productType = event ? event.target.value : this.element.querySelector('[name*="product_type"]')?.value
    console.log("Toggle fields for product type:", productType)

    this.fieldTargets.forEach(field => {
      const allowedTypes = field.dataset.types?.split(',') || []
      const requiredFor = field.dataset.requiredFor?.split(',') || []

      console.log("Field allowed types:", allowedTypes, "Should show:", allowedTypes.includes(productType))

      if (productType && allowedTypes.includes(productType)) {
        // Show field
        field.classList.remove('hidden')

        // Check if field should be required for this product type
        const isRequired = requiredFor.includes(productType)

        // Toggle required indicator (*)
        const indicator = field.querySelector('[data-required-indicator]')
        if (indicator) {
          if (isRequired) {
            indicator.classList.remove('hidden')
          } else {
            indicator.classList.add('hidden')
          }
        }

        // Toggle HTML5 required attribute
        const input = field.querySelector('input:not([type="hidden"]), select, textarea')
        if (input) {
          if (isRequired) {
            input.setAttribute('required', 'required')
          } else {
            input.removeAttribute('required')
          }
        }

        // TinyMCE controller will auto-detect visibility change via MutationObserver
      } else {
        // Hide field
        field.classList.add('hidden')

        // Remove required attribute when hidden
        const input = field.querySelector('input:not([type="hidden"]), select, textarea')
        if (input) {
          input.removeAttribute('required')
        }
      }
    })
  }
}
